script:
frappe.call({
	method: 'club_system.club_system.report.club_member_sports_report.club_member_sports_report.get_dashboard_data',
	callback: function(r) {
		if (r.message) {
			render_dashboard_card(r.message);
		}
	}
});

function render_dashboard_card(data) {
	const $card = $(frappe.render_template('member_sports_dashboard_card', data));
	$('.dashboard-card-member-sports-dashboard').html($card);
}

style:
.dashboard-card-member-sports-dashboard {
	padding: 16px;
}

.dashboard-card-member-sports-dashboard .stat-row {
	display: flex;
	justify-content: space-between;
	margin-bottom: 8px;
}

.dashboard-card-member-sports-dashboard .stat-item {
	flex: 1;
	text-align: center;
	padding: 12px;
	background: var(--card-bg);
	border-radius: 8px;
	margin: 0 4px;
	border: 1px solid var(--border-color);
}

.dashboard-card-member-sports-dashboard .stat-value {
	font-size: 24px;
	font-weight: 700;
	color: var(--text-primary);
}

.dashboard-card-member-sports-dashboard .stat-label {
	font-size: 11px;
	color: var(--text-muted);
	text-transform: uppercase;
	letter-spacing: 0.5px;
}

.dashboard-card-member-sports-dashboard .chart-preview {
	margin-top: 16px;
	height: 200px;
}

.dashboard-card-member-sports-dashboard .progress-bar-container {
	margin-top: 8px;
}

.dashboard-card-member-sports-dashboard .progress-bar {
	height: 6px;
	background: var(--border-color);
	border-radius: 3px;
	overflow: hidden;
}

.dashboard-card-member-sports-dashboard .progress-fill {
	height: 100%;
	border-radius: 3px;
	transition: width 0.5s ease;
}
